-- REVIEW BEFORE PRODUCTION. Apply after the M3 content and passage migrations.
-- No legacy prompts or answer rows are deleted/regenerated by this migration.
begin;
set local lock_timeout = '5s';
lock table public.uploaded_materials, public.comprehension_questions,
  public.comprehension_question_answers in access exclusive mode;

create table public.material_question_sets (
  id uuid primary key default gen_random_uuid(),
  material_id uuid not null references public.uploaded_materials(id) on delete cascade,
  created_by uuid not null references public.profiles(id) on delete restrict,
  name text not null check (length(btrim(name)) between 1 and 200),
  sequence_number integer not null check (sequence_number > 0),
  revision integer not null default 0 check (revision >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, material_id),
  unique (material_id, sequence_number)
);
alter table public.uploaded_materials add column next_question_set_number integer not null default 1
  check (next_question_set_number > 0);
alter table public.comprehension_questions add column question_set_id uuid;

-- Backfill all legacy material banks (including any historical non-Teacher
-- banks) to avoid orphaning real records. Only Teachers can create new sets.
insert into public.material_question_sets(id, material_id, created_by, name, sequence_number, created_at, updated_at)
select m.id, m.id, m.uploaded_by, 'Question Set 1', 1, min(q.created_at), max(q.updated_at)
from public.uploaded_materials m join public.comprehension_questions q on q.material_id = m.id
group by m.id, m.uploaded_by;
alter table public.comprehension_questions disable trigger comprehension_questions_set_updated_at;
update public.comprehension_questions set question_set_id = material_id where material_id is not null;
set constraints all immediate;
alter table public.comprehension_questions enable trigger comprehension_questions_set_updated_at;
alter table public.uploaded_materials disable trigger uploaded_materials_set_updated_at;
update public.uploaded_materials set next_question_set_number = 2
where id in (select material_id from public.material_question_sets);
alter table public.uploaded_materials enable trigger uploaded_materials_set_updated_at;
set constraints all deferred;

alter table public.comprehension_questions
  add constraint comprehension_questions_set_scope check (
    (material_id is not null and question_set_id is not null and module_id is null and passage_id is null)
    or (material_id is null and question_set_id is null)
  ),
  add constraint comprehension_questions_set_material_fkey
    foreign key (question_set_id, material_id) references public.material_question_sets(id, material_id) on delete restrict;
drop index public.comprehension_questions_material_order_key;
create unique index comprehension_questions_set_order_key
  on public.comprehension_questions(question_set_id, display_order) where question_set_id is not null;

create function public.m3_protect_question_set_identity() returns trigger
language plpgsql set search_path = '' as $$
begin
  if new.question_set_id is distinct from old.question_set_id then
    raise exception 'Question set membership is immutable';
  end if;
  return new;
end $$;
create trigger comprehension_questions_set_identity before update on public.comprehension_questions
  for each row execute function public.m3_protect_question_set_identity();

alter table public.material_question_sets enable row level security;
revoke all on public.material_question_sets from public, anon, authenticated;
grant select on public.material_question_sets to authenticated;
grant all on public.material_question_sets to service_role;
create policy "M3 admins and owning teachers read saved sets" on public.material_question_sets
for select to authenticated using (
  public.m3_current_role() = 'admin' or
  (public.m3_current_role() = 'teacher' and public.m3_owns_material(material_id))
);
-- Existing question and answer-key RLS is retained. Set IDs do not grant access.
-- Only the authenticated backend may mutate sets through this atomic RPC.
create function public.m3_write_material_question_set(
  actor_id uuid, target_material uuid, target_set uuid, operation text,
  expected_revision integer, bank jsonb
) returns uuid language plpgsql security invoker set search_path = '' as $$
declare
  actor_role text;
  owner_id uuid;
  next_number integer;
  saved_set public.material_question_sets%rowtype;
  item jsonb;
  old_question public.comprehension_questions%rowtype;
  answer_text text;
  answer_index integer;
  inserted_question_id uuid;
  position integer := 0;
begin
  select role into actor_role from public.profiles where id = actor_id;
  if actor_role is null or actor_role not in ('teacher', 'admin') then
    raise exception 'Question management requires a Teacher or Admin' using errcode = '42501';
  end if;
  select uploaded_by, next_question_set_number into owner_id, next_number
  from public.uploaded_materials where id = target_material for update;
  if not found or (actor_role <> 'admin' and owner_id <> actor_id) then
    raise exception 'Material unavailable to this account' using errcode = '42501';
  end if;
  if operation is null or operation not in ('create', 'regenerate', 'review') then
    raise exception 'Invalid question set operation' using errcode = '22023';
  end if;
  if operation <> 'review' and (actor_role <> 'teacher' or owner_id <> actor_id) then
    raise exception 'Only the owning Teacher may generate sets' using errcode = '42501';
  end if;
  if jsonb_typeof(bank) is distinct from 'array' then
    raise exception 'A six-question bank is required' using errcode = '22023';
  end if;
  if jsonb_array_length(bank) <> 6 or exists (
    select 1 from unnest(array['literal','inferential','critical']) category
    where (select count(*) from jsonb_array_elements(bank) q where q->>'type' = category) <> 2
  ) then
    raise exception 'Exactly two literal, two inferential and two critical questions are required' using errcode = '22023';
  end if;
  if operation = 'create' then
    if target_set is not null then raise exception 'New sets must not target an existing set' using errcode = '22023'; end if;
    insert into public.material_question_sets(material_id, created_by, name, sequence_number)
    values(target_material, actor_id, 'Question Set ' || next_number, next_number) returning * into saved_set;
    update public.uploaded_materials set next_question_set_number = next_number + 1 where id = target_material;
  else
    select * into saved_set from public.material_question_sets
    where id = target_set and material_id = target_material for update;
    if not found then raise exception 'Question set not found' using errcode = 'P0002'; end if;
    if expected_revision is distinct from saved_set.revision then
      raise exception 'This question set changed. Reload it before saving or regenerating.' using errcode = '40001';
    end if;
  end if;
  if operation = 'review' then
    if (select count(*) from public.comprehension_questions where question_set_id = saved_set.id) <> 6
      or (select count(distinct q->>'id') from jsonb_array_elements(bank) q) <> 6
      or exists(select 1 from jsonb_array_elements(bank) submitted where not exists (
        select 1 from public.comprehension_questions q where q.id = (submitted->>'id')::uuid
          and q.material_id = target_material and q.question_set_id = saved_set.id
      )) then
      raise exception 'Every edited question must belong to the selected set' using errcode = '42501';
    end if;
  elsif operation = 'regenerate' then
    -- Atomic replacement affects only this set. A failed insert rolls this back.
    delete from public.comprehension_questions where question_set_id = saved_set.id and material_id = target_material;
  end if;
  for item in select value from jsonb_array_elements(bank) loop
    position := position + 1;
    if operation = 'review' then
      select * into strict old_question from public.comprehension_questions
      where id = (item->>'id')::uuid and question_set_id = saved_set.id;
      select correct_answer into answer_text from public.comprehension_question_answers where question_id = old_question.id;
      select ordinality::integer - 1 into answer_index from jsonb_array_elements_text(old_question.options) with ordinality
      where value = answer_text;
      if answer_index is null then raise exception 'Invalid saved answer key' using errcode = '22023'; end if;
      update public.comprehension_questions set question_type = item->>'type', question_text = btrim(item->>'questionText'),
        options = item->'options', scaffolding_hint = btrim(item->>'scaffoldingHint'),
        review_status = 'reviewed', reviewed_by = actor_id, reviewed_at = now()
      where id = old_question.id;
      -- Retain answer-key identity/created_at and the system-selected option.
      update public.comprehension_question_answers set correct_answer = item->'options'->>answer_index
      where question_id = old_question.id;
    else
      insert into public.comprehension_questions(material_id, question_set_id, question_type, question_text,
        options, scaffolding_hint, display_order, generated_by_ai, review_status)
      values(target_material, saved_set.id, item->>'type', btrim(item->>'questionText'), item->'options',
        btrim(item->>'scaffoldingHint'), position, true, 'generated') returning id into inserted_question_id;
      insert into public.comprehension_question_answers(question_id, correct_answer) values(inserted_question_id, item->>'correctAnswer');
    end if;
  end loop;
  update public.material_question_sets set revision = revision + 1, updated_at = now() where id = saved_set.id;
  return saved_set.id;
end $$;
revoke all on function public.m3_protect_question_set_identity() from public, anon, authenticated;
revoke all on function public.m3_write_material_question_set(uuid,uuid,uuid,text,integer,jsonb) from public, anon, authenticated;
grant execute on function public.m3_write_material_question_set(uuid,uuid,uuid,text,integer,jsonb) to service_role;
commit;
